module bank(input logic [5:0] code, output wire [1:32] S);
  case_box u0(.code(code), .dout(S[1:4]));
  case_box u1(.code(code), .dout(S[6:9]));
  case_box u2(.code(code), .dout(S[9:12]));
  case_box u3(.code(code), .dout(S[13:16]));
  case_box u4(.code(code), .dout(S[17:20]));
  case_box u5(.code(code), .dout(S[21:24]));
  case_box u6(.code(code), .dout(S[25:28]));
  case_box u7(.code(code), .dout(S[29:32]));
endmodule
